// view, empty when it is fine. It works per table: a view may be migrated for
// some tables and pending for others (A-09a/A-09a2/A-09b, A-10a/A-10b) as long as the
// two sets are disjoint; an exempt view is neither migrated nor pending.
func classificationProblems(vt command.ViewType, migrated map[command.ViewType][]string, pending []pendingTable, exempt map[command.ViewType]string) []string {
	var problems []string
	mig := migrated[vt]

// migratedSources are the source prefixes (a directory ending in "/" or a file
// path, relative to internal/) of each migrated view. They are scanned for the
// retired mechanisms (criterion 2a/2b, and the hard-coded glyphs of 3). Only
// migrated views: pending ones still use them. A prefix may be a file so a view
// that migrates in two steps (OCI A-09a/A-09a2/A-09b, explorer A-10a/b) can be scanned
// file by file.
var migratedSources = map[command.ViewType][]string{
	command.ViewJobs:       {"ui/jobsview/"},
	}
	return b.state == browserStateTags && b.filterActive
}

// IsSearching returns true while registry tag queries are still in flight.
func (b *RegistryBrowser) IsSearching() bool {
	return b.pendingSearches > 0
}

// Update handles all messages for the browser.
func (b *RegistryBrowser) Update(msg tea.Msg) (*RegistryBrowser, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.KeyMsg:
		return b.handleKeyMsg(msg)
	case spinner.TickMsg:
		// Only a search turns this spinner, and it shows in the footer: a tag's
		// state is drawn by the activity column, which jobs.FrameMsg animates.
		if b.pendingSearches > 0 {
			var cmd tea.Cmd
			b.spinner, cmd = b.spinner.Update(msg)
			return b, cmd
		}
		return b, nil
	}
	return b.delegateUpdate(msg)
}

func (b *RegistryBrowser) delegateUpdate(msg tea.Msg) (*RegistryBrowser, tea.Cmd) {
	if b.state == browserStateInput && b.focusedField == brFieldRepo {
		var cmd tea.Cmd
		b.repoInput, cmd = b.repoInput.Update(msg)
		return b, cmd
	}

